def transform(grid):
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    freq = Counter(v for row in original for v in row)
    bg = freq.most_common(1)[0][0]
    ink = max((v for v in freq if v != bg), key=lambda v: freq[v])
    h, w = len(original), len(original[0])
    # Use the original grid to find all collinear endpoints, so filling a
    # horizontal gap cannot hide an endpoint needed for a vertical gap.
